param([Parameter(Mandatory=$true)][string]$OutputPath,[Parameter(Mandatory=$true)][string]$TaskSpecPath)
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$output=[IO.Path]::GetFullPath($OutputPath);$spec=[IO.Path]::GetFullPath($TaskSpecPath);$module=Join-Path $root 'scripts/tdimarc_native_outer_batch_finalizer_v2.lsp'
foreach($path in @($output,$spec,$module)){if(-not$path.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'GC7_PATH_OUTSIDE_PROJECT'}}
$base=& (Join-Path $PSScriptRoot 'build_full_scope_runtime_candidate_chain_v6.ps1') -OutputPath $output -TaskSpecPath $spec;if([string]$base.status-cne'PASS'){throw 'GC7_V6_BASE_FAILED'}
$text=[IO.File]::ReadAllText($output,[Text.Encoding]::UTF8);$autorun='(c:CXTDIMARCFULLBATCH)';if(([regex]::Matches($text,'(?m)^\(c:CXTDIMARCFULLBATCH\)\s*$')).Count-ne1){throw 'GC7_BASE_AUTORUN_COUNT'};$text=[regex]::Replace($text,'(?m)^\(c:CXTDIMARCFULLBATCH\)\s*$','',1)
$commandName='(defun c:CXTDIMARCFULLBATCH';$commandIndex=$text.LastIndexOf($commandName,[StringComparison]::Ordinal);if($commandIndex-lt0){throw 'GC7_ACTIVE_COMMAND_NOT_FOUND'};$text=$text.Substring(0,$commandIndex)+'(defun cx:obf2-base-batch'+$text.Substring($commandIndex+$commandName.Length)
$text=$text.Replace($commandName,'(defun cx:obf2-shadowed-batch')
$acceptName='(defun cx:fb-accept-one';$acceptIndex=$text.LastIndexOf($acceptName,[StringComparison]::Ordinal);if($acceptIndex-lt0){throw 'GC7_ACTIVE_ACCEPT_NOT_FOUND'};$text=$text.Substring(0,$acceptIndex)+'(defun cx:obf2-base-accept-one'+$text.Substring($acceptIndex+$acceptName.Length)
$activeStart=$text.LastIndexOf('(defun cx:obf2-base-batch',[StringComparison]::Ordinal);$activeEnd=$text.IndexOf('(defun cx:cs-segment-items',$activeStart,[StringComparison]::Ordinal);if($activeStart-lt0-or$activeEnd-le$activeStart){throw 'GC7_ACTIVE_BATCH_RANGE'};$active=$text.Substring($activeStart,$activeEnd-$activeStart)
$pattern='\(setq\s+cx:\*fb-phase\*\s+\(strcat\s+"RUN_"\s+segment-type\)\s+one-result';if(([regex]::Matches($active,$pattern)).Count-ne1){throw 'GC7_SEGMENT_START_INJECTION_POINT'};$replacement='(setq cx:*fb-phase* (strcat "RUN_" segment-type))'+[Environment]::NewLine+'                        (cx:obf2-segment-start group source-handle segment-type segment-index)'+[Environment]::NewLine+'                        (setq one-result';$active=[regex]::Replace($active,$pattern,$replacement,1);$text=$text.Substring(0,$activeStart)+$active+$text.Substring($activeEnd)
$cursor=[IO.Path]::Combine([IO.Path]::GetDirectoryName($output),'generation_segment_cursor.tsv').Replace('\','/');$receipt=[IO.Path]::Combine([IO.Path]::GetDirectoryName($output),'generation_outer_finalizer.tsv').Replace('\','/');$bindings='(setq cx:*obf2-cursor-path* "'+$cursor+'" cx:*obf2-finalizer-path* "'+$receipt+'")'+[Environment]::NewLine;$outer=[IO.File]::ReadAllText($module,[Text.Encoding]::UTF8).Trim();$text=$text.TrimEnd()+[Environment]::NewLine+$bindings+$outer+[Environment]::NewLine+$autorun+[Environment]::NewLine
[IO.File]::WriteAllText($output,$text,[Text.UTF8Encoding]::new($false));$final=[IO.File]::ReadAllText($output,[Text.Encoding]::UTF8)
foreach($token in @('SEGMENT_START_BEFORE_NATIVE_ROUTE','OUTER_VECTOR_V2','OUTER_BATCH_FINALIZER_V2','MISSING_REPORTS_RECONSTRUCTED_FROM_RUNTIME_VECTOR_LEDGER','EXISTING_AUTHORITATIVE_REPORTS_PRESERVED','OUTER_FINALIZER_UNSETTLED_ROUTE','(defun cx:obf2-base-batch','(defun cx:obf2-base-accept-one','(defun c:CXTDIMARCFULLBATCH')){if(-not$final.Contains($token,[StringComparison]::Ordinal)){throw "GC7_REQUIRED:$token"}}
if(([regex]::Matches($final,'(?m)^\(c:CXTDIMARCFULLBATCH\)\s*$')).Count-ne1){throw 'GC7_FINAL_AUTORUN_COUNT'};if(([regex]::Matches($final,'\(defun c:CXTDIMARCFULLBATCH')).Count-ne1){throw 'GC7_PUBLIC_COMMAND_COUNT'}
$activeOuter=$final.Substring($final.LastIndexOf('(defun cx:obf2-text',[StringComparison]::Ordinal));foreach($literal in @('87/ARC/2','8C/ARC/6','8B/ARC/2','88/ARC/7','87/ARC/6','87/ARC/7')){if($activeOuter.Contains($literal,[StringComparison]::OrdinalIgnoreCase)){throw "GC7_BOARD_LITERAL:$literal"}}
$lexical=& (Join-Path $PSScriptRoot 'assert_autolisp_lexical_balance_v1.ps1') -LispPath $output;if([string]$lexical.status-cne'PASS'-or[int]$lexical.final_depth-ne0){throw 'GC7_LEXICAL'}
[pscustomobject]@{status='PASS';task_count=[int]$base.task_count;segment_cursor='BEFORE_EACH_NATIVE_ROUTE';acceptance_vector='AFTER_EXISTING_ACCEPTANCE_GATE';outer_finalizer='NORMAL_SILENT_AND_ERROR_RETURN';normal_reports='PRESERVED';missing_reports='RECONSTRUCTED_FROM_RUNTIME_VECTOR_LEDGER';cad_send_count_added=0;retry_count=0;save_count=0;board_specific_algorithm_literals=0;lexical_balance='PASS';sha256=(Get-FileHash -LiteralPath $output -Algorithm SHA256).Hash}
